from science_v2.k import Unit
U = Unit("s4u05")
U.q("E", "5.1", "O1", 'Mo says we see things because light comes out of our eyes. What really happens?', ('Light from a source bounces off objects into our eyes', 'Our eyes receive light.'), [('He is right', 'Eyes do not shine light.'), ('We see in total darkness', 'With no light we cannot see.')], d="M")
U.q("P", "5.2", "O2", 'Light is shone through three cards with holes. When will it reach the wall?', ('Only when all the holes are in a straight line', 'Light travels in straight lines.'), [('Always', 'Light cannot bend round the cards.'), ('Never', 'It passes when the holes line up.')], d="M")
U.q("R", "5.3", "O3", 'Which surface reflects light best?', ('A mirror', 'Smooth, shiny surfaces reflect well.'), [('Black cloth', 'Black cloth reflects very little.'), ('A brick', 'A brick is rough and dull.')], d="M")
U.q("R", "5.4", "O4", 'Which object in the solar system makes its own light?', ('The Sun', 'The planets and the Moon reflect sunlight.'), [('The Moon', 'The Moon reflects light.'), ('Mars', 'Mars reflects light.')], d="M")
U.q("E", "5.5", "O5", 'Sara says night happens because the Sun goes out. What really happens?', ('The Earth spins, so our side faces away from the Sun', 'The Sun keeps shining.'), [('She is right', 'The Sun does not go out.'), ('The Moon covers the Sun every night', 'That is not why night happens.')], d="M")
U.q("P", "5.6", "O6", 'At midday the Sun is high in the sky. How long are shadows?', ('Short', 'High light makes short shadows.'), [('Very long', 'Long shadows happen when the Sun is low.'), ('There are no shadows', 'Objects still make shadows.')], d="M")
V2 = U.V2
